  // ../src/styles.css
  var styles_default = `/* Shadow-DOM styles for the editor chrome. Imported as text by shell.js
 * and injected into the shadow root, so host-page CSS can't reach it \u2014
 * and these rules can't leak out. */

:host{all:initial}

/* ---- chrome palette ----
   The editor's dark surfaces \u2014 the bottom bar, the tool rail, the
   floating pills, the overflow menu \u2014 as custom properties, so the
   light scheme is a swap of this block rather than a second copy of
   every rule. Panels and dialogs are not in here: they are white in
   both schemes, being documents rather than chrome.

   \`all:initial\` above does not touch custom properties, so these
   survive it. The light values are the same surfaces read the other
   way up: a white face, ink-coloured text, and a hairline ring that is
   invisible in the dark scheme (an inset shadow, so switching it on
   costs no layout).

   The site settings dialog picks the scheme; a site with a dark design
   of its own wants the light one, because dark chrome over a dark page
   is chrome you have to hunt for. ---- */
:host{
--cms-chrome-bg:#1c2128;      /* the pill/rail/toolbar face */
--cms-chrome-hi:#2a3140;      /* that face, raised: hover on a whole pill */
--cms-chrome-menu:#242a33;    /* the overflow menu, a step off the bar */
--cms-chrome-fg:#fff;
--cms-chrome-line:rgba(255,255,255,.28);  /* borders drawn on the face */
--cms-chrome-line-2:rgba(255,255,255,.4); /* the same, asking to be noticed */
--cms-chrome-ring:transparent;            /* hairline the light face needs */
--cms-wash-1:rgba(255,255,255,.1);   /* hover on a bar button, a menu row */
--cms-wash-2:rgba(255,255,255,.14);  /* hover on the rail; the status chip */
--cms-wash-3:rgba(255,255,255,.18);  /* hover on an icon button */
--cms-wash-4:rgba(255,255,255,.2);   /* a control that is currently on */
--cms-chrome-dngr:#fca5a5;                 /* delete/discard actions */
--cms-chrome-dngr-wash:rgba(252,165,165,.2);
--cms-chrome-shadow:0 8px 24px rgba(0,0,0,.35);
--cms-chrome-shadow-sm:0 4px 12px rgba(0,0,0,.35);
--cms-chrome-shadow-rail:2px 0 12px rgba(0,0,0,.25);
}
:host(.light){
--cms-chrome-bg:#fff;
--cms-chrome-hi:#f1f3f6;
--cms-chrome-menu:#fff;
--cms-chrome-fg:#1c2128;
--cms-chrome-line:#d9dce1;
--cms-chrome-line-2:#98a2b3;
--cms-chrome-ring:#dfe3e8;
--cms-wash-1:rgba(28,33,40,.06);
--cms-wash-2:rgba(28,33,40,.08);
--cms-wash-3:rgba(28,33,40,.1);
--cms-wash-4:rgba(47,95,224,.14);
--cms-chrome-dngr:#c0392b;
--cms-chrome-dngr-wash:rgba(192,57,43,.1);
--cms-chrome-shadow:0 8px 24px rgba(15,18,25,.22);
--cms-chrome-shadow-sm:0 4px 12px rgba(15,18,25,.2);
--cms-chrome-shadow-rail:2px 0 12px rgba(15,18,25,.14);
}
*{box-sizing:border-box;font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif}
/* Author display rules (inline-flex buttons etc.) would otherwise
   beat the UA's [hidden]{display:none}. */
[hidden]{display:none!important}

/* ---- bottom pill bar (dark) ---- */
.bar{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:2147483000;
display:flex;align-items:center;gap:8px;background:var(--cms-chrome-bg);color:var(--cms-chrome-fg);
border-radius:999px;
padding:8px 14px;font-size:13px;line-height:1;white-space:nowrap;
box-shadow:var(--cms-chrome-shadow),inset 0 0 0 1px var(--cms-chrome-ring);
transition:transform .25s ease,opacity .25s ease}
.bar.min{transform:translateX(-50%) scale(.25);opacity:0;pointer-events:none}
.fab{position:fixed;bottom:20px;left:50%;z-index:2147483000;width:48px;height:48px;
border-radius:50%;background:var(--cms-chrome-bg);color:var(--cms-chrome-fg);border:none;cursor:pointer;
box-shadow:var(--cms-chrome-shadow),inset 0 0 0 1px var(--cms-chrome-ring);
display:flex;align-items:center;justify-content:center;padding:0;
transform:translateX(-50%) scale(.25);opacity:0;pointer-events:none;
transition:transform .25s ease,opacity .25s ease}
.fab.on{transform:translateX(-50%) scale(1);opacity:1;pointer-events:auto}
.fab:hover{background:var(--cms-chrome-hi)}
.fab svg{width:20px;height:20px;fill:currentColor}
.chip{padding:3px 10px;border-radius:999px;background:var(--cms-wash-2);font-size:12px;text-transform:capitalize}
/* The two coloured chips carry their own meaning, so they keep their
   colours in both schemes \u2014 and with them their own white text, which
   the light bar's ink-coloured default would not survive. */
.chip.published{background:#1e7e4e;color:#fff}
.chip.changes{background:#b45309;color:#fff;text-transform:none}
/* ---- toast: status and confirmation messages, floated above the bar
   so they're visible even when the bar is busy or minimized ---- */
.toast{position:fixed;bottom:76px;left:50%;transform:translateX(-50%) translateY(8px);
z-index:2147483007;background:var(--cms-chrome-bg);color:var(--cms-chrome-fg);border-radius:10px;
padding:10px 16px;
font-size:13px;line-height:1.4;max-width:min(28em,90vw);text-align:center;
box-shadow:var(--cms-chrome-shadow),inset 0 0 0 1px var(--cms-chrome-ring);
opacity:0;pointer-events:none;visibility:hidden;
transition:transform .2s ease,opacity .2s ease,visibility .2s}
.toast.on{transform:translateX(-50%) translateY(0);opacity:1;visibility:visible}
.bar button{font:inherit;color:var(--cms-chrome-fg);background:transparent;border:1px solid var(--cms-chrome-line);
border-radius:999px;padding:5px 12px;cursor:pointer;display:inline-flex;align-items:center;gap:6px}
.bar button svg{width:13px;height:13px;fill:currentColor;flex-shrink:0}
.bar .ic{display:inline-flex}
.bar button:hover{background:var(--cms-wash-1)}
.bar button:disabled{opacity:.4;cursor:default}
/* Publish stays the same blue in both schemes, white text and all. */
.bar button.primary{background:#2f5fe0;border-color:#2f5fe0;color:#fff}
.bar button.primary:hover{background:#2149b8}
.bar button.quiet{border-color:transparent;opacity:.7;padding:5px 8px}
/* Amber ring on Save while there are unsaved changes. */
.bar button.attn{border-color:#f0b429}

/* ---- overflow (\u22EF) menu: rare and destructive actions ---- */
.more{position:relative;display:inline-flex}
#more{font-size:16px;padding:4px 10px;line-height:1}
.menu{position:absolute;bottom:calc(100% + 12px);right:0;display:none;flex-direction:column;
background:var(--cms-chrome-menu);border-radius:12px;padding:6px;min-width:190px;
box-shadow:var(--cms-chrome-shadow),inset 0 0 0 1px var(--cms-chrome-ring)}
.menu.on{display:flex}
.menu button,.menu a{font:inherit;font-size:13px;color:var(--cms-chrome-fg);background:none;border:none;border-radius:8px;
padding:8px 12px;text-align:left;cursor:pointer;white-space:nowrap;text-decoration:none;display:block}
.menu button:hover,.menu a:hover{background:var(--cms-wash-1)}
.menu button.dngr{color:var(--cms-chrome-dngr)}
.menu button.dngr:hover{background:var(--cms-chrome-dngr-wash)}
.menu hr{border:none;border-top:1px solid var(--cms-wash-2);margin:4px 6px}

/* ---- page CSS & JS panel (wide, admin-only) ---- */
.code-overlay{position:fixed;inset:0;background:rgba(15,18,25,.5);z-index:2147482998;display:none}
.code-overlay.on{display:block}
.codepanel{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:2147482999;
width:min(1000px,94vw);height:min(680px,88vh);background:#fff;color:#1c2128;border-radius:12px;
box-shadow:0 16px 48px rgba(0,0,0,.4);display:none;flex-direction:column;overflow:hidden}
.codepanel.on{display:flex}
.chead{display:flex;align-items:center;gap:18px;padding:10px 16px;border-bottom:1px solid #e3e6ea}
.chead h2{margin:0;font-size:15px;white-space:nowrap}
.ctabs{display:flex;gap:4px}
.ctabs button{border:none;background:none;padding:8px 14px;font-size:13px;color:#667085;
cursor:pointer;border-bottom:2px solid transparent;border-radius:0}
.ctabs button:hover{color:#1c2128}
.ctabs button.on{color:#2149b8;border-bottom-color:#2f5fe0;font-weight:600}
#code-close,#src-close{margin-left:auto;border:none;background:none;font-size:20px;line-height:1;
padding:4px 9px;color:#667085;cursor:pointer;border-radius:6px}
#code-close:hover,#src-close:hover{background:#eceef1;color:#1c2128}
.cbody{flex:1;position:relative;background:#11151c;min-height:0}
#code-hl,#code-ta,#src-hl,#src-ta{position:absolute;inset:0;margin:0;padding:14px 16px;border:none;
font:13px/1.55 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre;tab-size:4}
#code-hl,#src-hl{color:#d5dbe5;overflow:hidden;pointer-events:none}
/* The universal reset sets font-family on every element \u2014 token
   spans must stay in the editor's monospace or the visible text
   drifts out of alignment with the textarea's caret. */
#code-hl span,#src-hl span{font:inherit}
#code-ta,#src-ta{resize:none;background:transparent;color:transparent;caret-color:#fff;outline:none;
overflow:auto}
#code-ta::selection,#src-ta::selection{background:rgba(47,95,224,.45);color:transparent}
.tok-c{color:#7d8799} /* comments */
.tok-s{color:#9ecbff} /* strings */
.tok-k{color:#ff7b8a} /* keywords / at-rules */
.tok-p{color:#b392f0} /* CSS properties */
.tok-n{color:#f2cc60} /* numbers / colors */
.cfoot{display:flex;gap:8px;align-items:center;padding:10px 14px;border-top:1px solid #e3e6ea}
.chint{flex:1;font-size:12px;color:#667085}
/* validation error in the source panel's footer (replaces the hint) */
.cfoot .derr{flex:1;font-size:12px;color:#c0392b;font-weight:600}

/* ---- floating button-editor chrome (gear/trash by a clicked button) ---- */
.btnui{position:fixed;z-index:2147483000;display:none;gap:2px;background:var(--cms-chrome-bg);
border:1px solid var(--cms-chrome-line);border-radius:999px;padding:4px 6px;
box-shadow:var(--cms-chrome-shadow-sm)}
.btnui.on{display:flex}
.btnui button{font:15px/1 system-ui,sans-serif;color:var(--cms-chrome-fg);background:transparent;border:none;
border-radius:999px;padding:6px 9px;cursor:pointer;display:inline-flex}
/* The display above is an author rule, so it outranks the browser's own
   [hidden]{display:none} and a hidden control would show regardless.
   Slot chrome hides its trash can this way when there is no chosen
   picture to remove. */
.btnui button[hidden]{display:none}
.btnui button:hover{background:var(--cms-wash-3)}
.btnui button svg{display:block;width:15px;height:15px;fill:currentColor}
#btn-del,#snip-del,#img-del,#vid-del,#slot-clear,#col-del{color:var(--cms-chrome-dngr)}
#btn-del:hover,#snip-del:hover,#img-del:hover,#vid-del:hover,
#slot-clear:hover,#col-del:hover{background:var(--cms-chrome-dngr-wash)}
#snip-move{cursor:grab;font-size:13px;letter-spacing:1px}
/* The column tool is drawn on the row's top border (placeColUI centres
   it there), so it covers nothing and can stay legible. Smaller and a
   touch quieter than the block chrome above it all the same: it edits a
   part of the block, not the block. */
/* The column and question tools are secondary to the block chrome, and
   read that way: slightly recessed until pointed at. */
#col-ui,#faq-ui{padding:2px 4px;opacity:.85;transition:opacity .12s}
#col-ui:hover,#faq-ui:hover{opacity:1}
#col-ui button{padding:4px 6px}
#col-ui button svg{width:13px;height:13px}

/* Chrome that has to get out of the way of a drag without forgetting
   what it was attached to. Nothing repositions the pills mid-gesture,
   so left visible they would sit stale over a row that is moving. */
.btnui.dim{opacity:0;pointer-events:none}

/* ---- column resize handles ----
   One per gutter in the active row, drawn on the boundary between two
   columns. The hit area is wider than the line and wider than the
   gutter it sits in: gap-6 is 24px, which is under any touch target
   worth the name, so the handle overhangs into both columns while the
   line it draws stays where the boundary actually is. Below the pills
   in z-order (they are 2147483000) and below the rail, since it is
   drawn over page content rather than over the chrome.
   touch-action is what stops a touch drag scrolling the page instead. */
#col-handles .colhandle{position:fixed;z-index:2147482998;width:24px;
margin-left:-12px;cursor:col-resize;display:flex;align-items:center;
justify-content:center;touch-action:none}
#col-handles .colhandle[hidden]{display:none}
.colhandle::before{content:"";width:2px;height:100%;border-radius:1px;
background:rgba(37,99,235,.35);transition:background .12s,width .12s}
.colhandle:hover::before,.colhandle.on::before{width:4px;background:#2563eb}

/* ---- tool rail (left edge, edit mode only) ---- */
.rail{position:fixed;top:0;left:0;bottom:0;width:56px;z-index:2147482999;
background:var(--cms-chrome-bg);display:none;flex-direction:column;align-items:center;
padding-top:14px;gap:6px;
box-shadow:var(--cms-chrome-shadow-rail),inset -1px 0 0 var(--cms-chrome-ring)}
.rail.on{display:flex}
.rail button{width:46px;height:46px;border-radius:10px;border:none;background:transparent;
color:var(--cms-chrome-fg);cursor:pointer;display:flex;flex-direction:column;align-items:center;
justify-content:center;gap:3px;font-size:17px;line-height:1;padding:0}
.rail button span{font-size:9px;opacity:.75;letter-spacing:.02em}
.rail button:hover:not(:disabled){background:var(--cms-wash-2)}
.rail button.on{background:var(--cms-wash-4)}
.rail button:disabled{opacity:.35;cursor:default}

/* ---- media modal (light, centered) ---- */
/* Sits above the small dialog: section settings can open the
   picker to choose a background image while the dialog stays. */
.overlay{position:fixed;inset:0;background:rgba(15,18,25,.5);z-index:2147483003;display:none}
.overlay.on{display:block}
.panel{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:2147483004;
width:min(940px,94vw);height:min(640px,88vh);background:#fff;color:#1c2128;
border-radius:12px;box-shadow:0 16px 48px rgba(0,0,0,.4);display:none;flex-direction:column;overflow:hidden}
.panel.on{display:flex}
.panel button{font:inherit;color:#1c2128;background:#fff;border:1px solid #d9dce1;
border-radius:8px;padding:6px 12px;cursor:pointer;font-size:13px}
.panel button:hover{background:#f4f5f7}
.head{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid #e3e6ea}
.head h2{margin:0;font-size:15px;white-space:nowrap}
#search{flex:1;min-width:0;padding:7px 12px;border:1px solid #d9dce1;border-radius:8px;font:inherit;font-size:13px}
.views{display:flex;gap:2px}
.views button{padding:6px 10px}
.views button.on{background:#e8edfb;border-color:#2f5fe0;color:#2149b8}
#picker-close{border:none;font-size:20px;line-height:1;padding:4px 9px;color:#667085}
#picker-close:hover{background:#eceef1;color:#1c2128}
.pbody{flex:1;display:flex;min-height:0}
.side{width:200px;flex-shrink:0;border-right:1px solid #e3e6ea;overflow-y:auto;padding:10px}
.side button{display:block;width:100%;text-align:left;border:none;background:none;
padding:8px 10px;border-radius:8px;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.side button.on{background:#e8edfb;color:#2149b8;font-weight:600}
.side button .n{color:#98a2b3;font-size:11px;margin-left:4px}
.side .newf{color:#667085;margin-top:8px;border-top:1px solid #eceef1;border-radius:0;padding-top:12px}
.side .newf:hover{color:#2149b8;background:none}
.main{flex:1;display:flex;flex-direction:column;min-width:0}
.up{display:flex;gap:8px;align-items:center;padding:10px 14px;border-bottom:1px solid #e3e6ea}
.up input[type=file]{font-size:12px;min-width:0;flex:1}
.items{flex:1;overflow-y:auto;padding:14px}
.items.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px;align-content:start;
/* Rows sized by their tile, not by the box. Left as auto, a stretched
   tile whose figure clips its own overflow contributes no height, so a
   folder with enough files gets every row squeezed to a sliver until
   they all fit and the panel never scrolls. align-items keeps a short
   last row from stretching to the tallest track. */
grid-auto-rows:max-content;align-items:start}
.items.grid figure{margin:0;cursor:pointer;border:2px solid transparent;border-radius:8px;overflow:hidden}
.items.grid figure:hover{border-color:#2f5fe0}
.items.grid img{display:block;width:100%;height:92px;object-fit:cover}
.items.grid .doc{display:flex;align-items:center;justify-content:center;height:92px;background:#f4f5f7;font-size:30px}
.items.grid .doc span{font-size:11px;font-weight:700;color:#667085;margin-left:4px;text-transform:uppercase}
.items.grid figcaption{font-size:11px;padding:4px 6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.items.list .row{display:flex;align-items:center;gap:12px;padding:7px 10px;border-radius:8px;cursor:pointer}
.items.list .row:hover{background:#f4f5f7}
.items.list img{width:44px;height:44px;object-fit:cover;border-radius:6px;flex-shrink:0}
.items.list .doc{width:44px;height:44px;display:flex;align-items:center;justify-content:center;
background:#f4f5f7;border-radius:6px;font-size:20px;flex-shrink:0}
.items.list .nm{flex:1;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.items.list .sz{color:#667085;font-size:12px;white-space:nowrap}
.empty{color:#667085;font-size:13px}

/* ---- snippet drawer: slides out leftward from beside the tool
   rail (non-modal, so drag-and-drop can reach the page) ---- */
.drawer{position:fixed;top:0;left:56px;bottom:0;width:300px;z-index:2147482997;
background:#fff;color:#1c2128;box-shadow:8px 0 32px rgba(0,0,0,.18);
display:flex;flex-direction:column;transform:translateX(-130%);transition:transform .25s ease}
.drawer.on{transform:translateX(0)}
.drawer .dhead{display:flex;align-items:center;justify-content:space-between;
padding:14px 16px;border-bottom:1px solid #e3e6ea}
.drawer .dhead h2{margin:0;font-size:15px}
.drawer .dhead button{border:none;background:none;font-size:20px;line-height:1;
padding:4px 9px;color:#667085;cursor:pointer;border-radius:6px}
.drawer .dhead button:hover{background:#eceef1;color:#1c2128}
.drawer .dhint{padding:10px 16px;font-size:12px;color:#667085;border-bottom:1px solid #eceef1}
.drawer .dhead .dactions{display:flex;align-items:center;gap:2px}
.drawer .dhead .dactions button svg{width:16px;height:16px;fill:currentColor;display:block}
.drawer .dhead #drawer-search-btn.on{background:#eceef1;color:#1c2128}
.drawer .dsearch{padding:8px 16px;border-bottom:1px solid #eceef1}
.drawer .dsearch input{width:100%;padding:6px 8px;border:1px solid #d9dce1;border-radius:8px;
  font:inherit;font-size:13px;color:#1c2128;background:#fff}
.drawer .dcat{padding:8px 16px;border-bottom:1px solid #eceef1}
.drawer .dcat select{width:100%;padding:6px 8px;border:1px solid #d9dce1;border-radius:8px;
  font:inherit;font-size:13px;color:#1c2128;background:#fff;cursor:pointer}
.dlist .snip.cat-hide{display:none}
.drawer .dlist{flex:1;overflow-y:auto;padding:12px;display:flex;flex-direction:column}
.snip{border:1px solid #d9dce1;border-radius:10px;padding:12px;margin-bottom:10px;
cursor:grab;background:#fff}
.snip:hover{border-color:#2f5fe0;box-shadow:0 2px 8px rgba(47,95,224,.12)}
.snip .sname{font-size:13px;font-weight:600;margin:0 0 3px}
/* Section presets: inline-insert mode hides them; add-a-section mode
   lists them first, clickable rather than draggable. */
.snip.preset{cursor:pointer}
/* The custom-code card has no thumbnail: it stands for a library
   entry chosen on click, not for markup of its own. */
.snip.code{cursor:pointer}
.snip.code .sdesc{margin-top:2px}
/* Adding a section: every card is a click target, so none of them
   should invite the drag that cannot create one. */
.dlist.sections-mode .snip{cursor:pointer}
.dlist:not(.sections-mode) .snip.preset{display:none}
.dlist.sections-mode .snip.preset{order:-1}
.snip .stag{margin-left:8px;padding:2px 7px;border-radius:999px;background:#e8edfc;
color:#2f5fe0;font-size:10px;font-weight:600;vertical-align:1px}
/* Thumbnails: real snippet markup rendered page-wide in an iframe
   (which brings its own copy of the host CSS across the shadow
   boundary) and scaled to card size. Section presets (.sect) render
   full sections, so they get a taller crop; the iframe height is the
   crop height divided by the scale factor. */
.snip .sthumb{height:80px;margin:2px 0 6px;border:1px solid #eceef1;border-radius:6px;
overflow:hidden;background:#f9fafb;pointer-events:none}
.snip .sthumb iframe{border:0;width:720px;height:231px;transform:scale(.347);
transform-origin:0 0;background:#fff}
.snip .sthumb.sect{height:110px}
.snip .sthumb.sect iframe{height:317px}
.snip .sdesc{font-size:11px;color:#667085;margin:0;overflow:hidden;display:-webkit-box;
-webkit-line-clamp:2;-webkit-box-orient:vertical}

/* ---- small buttons shared by the code panel footer ---- */
.mbtn{font:12px system-ui,sans-serif;color:#1c2128;background:#fff;border:1px solid #d9dce1;
border-radius:8px;padding:7px 12px;cursor:pointer}
.mbtn:hover{background:#f4f5f7}
.mbtn.primary{background:#2f5fe0;border-color:#2f5fe0;color:#fff}
.mbtn.primary:hover{background:#2149b8}

/* ---- menu-item modal: the searchable page picker and Remove ---- */
.combo{position:relative}
.combo-list{position:absolute;top:calc(100% + 4px);left:0;right:0;z-index:5;background:#fff;
border:1px solid #d9dce1;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.18);
max-height:180px;overflow-y:auto;padding:4px}
/* .dlg over .combo-list: outranks the later generic .dlg button rule,
   which would otherwise restyle the suggestions as bordered buttons. */
.dlg .combo-list button{display:block;width:100%;text-align:left;border:none;background:none;
padding:7px 10px;border-radius:6px;font-size:13px;white-space:nowrap;overflow:hidden;
text-overflow:ellipsis}
.dlg .combo-list button:hover{background:#e8edfb;color:#2149b8}
.combo-list .none{padding:7px 10px;font-size:12px;color:#667085}
.dlg .acts .rm{margin-right:auto;color:#c0392b;border-color:#eac3bd}
.dlg .acts .rm:hover{background:#fdf2f0}
/* radio rows under the "Links to" heading */
#mm .fld label.chk{margin:0 0 6px}

/* ---- small dialog (replaces window.confirm / window.prompt) ----
   A dialog sits below .overlay/.panel by default, because a dialog can
   open the media picker for one of its fields and must stay behind it.
   The reverse also happens \u2014 the picker asks for a new folder name \u2014 so
   openDialog adds .over when it opens on top of a panel, which lifts the
   dialog above it for as long as it's up. ---- */
.dlg-overlay{position:fixed;inset:0;background:rgba(15,18,25,.5);z-index:2147483001;display:none}
.dlg-overlay.on{display:block}
/* A column: heading, tab bar and actions hold their place while the
   controls between them scroll. Before this the whole dialog scrolled,
   which put Save below the fold of anything with more than a screenful
   of settings \u2014 the one button the dialog exists for. */
.dlg{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:2147483002;
width:min(400px,92vw);background:#fff;color:#1c2128;border-radius:12px;
box-shadow:0 16px 48px rgba(0,0,0,.4);padding:20px;display:none;
max-height:88vh;flex-direction:column}
.dlg.on{display:flex}
/* min-height:0 is what lets this shrink below its content and scroll \u2014
   a flex item's floor is its content size otherwise, and the dialog
   would grow past max-height instead. */
.dlg .dbody{flex:0 1 auto;min-height:0;overflow-y:auto}
.dlg-overlay.over{z-index:2147483005}
.dlg.over{z-index:2147483006}
/* Settings panels: wider, and two fields to a row so a tab's worth of
   controls is taken in at a glance rather than scrolled through. */
.dlg.wide{width:min(720px,94vw)}
/* Top-anchored while tabbed, so switching tabs moves the content below
   the bar and never the bar itself. */
.dlg.tabbed{top:7vh;transform:translateX(-50%);max-height:86vh}
.dlg.wide #dlg-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}
.dlg.wide #dlg-fields .fld.span{grid-column:1 / -1}
@media (max-width:560px){.dlg.wide #dlg-fields{grid-template-columns:1fr}}
.dlg p{margin:0 0 14px;font-size:14px;line-height:1.45}
.dlg input{width:100%;padding:8px 12px;border:1px solid #d9dce1;border-radius:8px;
font:inherit;font-size:13px;margin-bottom:14px}
.dlg input:focus{outline:2px solid #2f5fe0;border-color:#2f5fe0}
/* inline validation error under the prompt input */
.dlg input.invalid{border-color:#c0392b}
.dlg input.invalid:focus{outline-color:#c0392b}
.dlg p.derr{color:#c0392b;font-size:12px;margin:-8px 0 12px}
.dlg .fld{margin:0 0 12px}
.dlg .fld label{display:block;font-size:12px;font-weight:600;margin-bottom:4px;color:#475467}
/* color / image field rows in dialogs */
.dlg .crow,.dlg .irow{display:flex;gap:8px;align-items:center}
.dlg .crow input[type=color]{width:38px;height:30px;padding:2px;border:1px solid #d9dce1;
border-radius:6px;background:#fff;cursor:pointer}
.dlg .cval{flex:1;font-size:12px;color:#667085}
.dlg .crow button,.dlg .irow button{padding:4px 10px;font-size:12px}
.dlg .irow img{width:48px;height:34px;object-fit:cover;border-radius:6px;border:1px solid #d9dce1}
.dlg .crow input,.dlg .irow input{margin:0}
/* computed note under a field: explanation, not input, so it carries
   its own spacing and its wrapper carries none */
.dlg .fld.note{margin:0}
.dlg .fnote{margin:-4px 0 12px;font-size:11px;line-height:1.45;color:#667085}
/* range field (slider + numeric input) */
.dlg .rrow{display:flex;gap:10px;align-items:center}
.dlg .rrow input[type=range]{flex:1;width:auto;margin:0;padding:0}
.dlg .rnum{width:64px;margin:0;padding:5px 8px}
/* live preview pane */
#dlg-preview{margin:0 0 14px;padding:20px;border:1px solid #e3e6ea;border-radius:8px;
background:#f8f9fb;display:flex;justify-content:center;align-items:center;min-height:72px}
/* plain text + checkbox fields (label.chk must out-rank the
   .dlg .fld label heading rule, which sets display:block) */
.dlg .tinput{margin:0}
/* multi-line text field (site-wide CSS/JS) */
.dlg textarea.tinput{width:100%;padding:8px 12px;border:1px solid #d9dce1;border-radius:8px;
font:inherit;font-size:13px;resize:vertical;box-sizing:border-box}
.dlg textarea.tinput:focus{outline:2px solid #2f5fe0;border-color:#2f5fe0}
/* Rich field: a small toolbar over an editable box, styled to read as
   one control with the plain inputs beside it. */
.dlg .rich{border:1px solid #d9dce1;border-radius:8px;overflow:hidden;background:#fff}
.dlg .rich:focus-within{outline:2px solid #2f5fe0;border-color:#2f5fe0}
.dlg .rtb{display:flex;gap:2px;padding:4px 6px;background:#f7f8fa;
border-bottom:1px solid #e3e6ea}
.dlg .rtb button{display:inline-flex;align-items:center;justify-content:center;
border:none;background:none;border-radius:6px;padding:3px 9px;height:26px;
font-size:13px;line-height:1;color:#475467;min-width:28px}
/* The icon buttons sit on the same baseline and weight as the lettered
   ones; the glyphs are 24-unit drawings scaled down here rather than at
   their shipped size. */
.dlg .rtb button svg{width:17px;height:17px;fill:currentColor}
.dlg .rtb button:hover{background:#e8edfb;color:#2149b8}
.dlg .rtb button.on{background:#e8edfb;color:#2149b8}
.dlg .rted{padding:8px 12px;font-size:13px;line-height:1.5;min-height:44px;
outline:none;word-break:break-word}
.dlg .rted a{color:#2149b8}
/* The placeholder for an empty box. contenteditable is never really
   empty \u2014 a stray <br> lives there \u2014 so the class is set from the text
   rather than by :empty. */
.dlg .rted.empty::before{content:attr(data-placeholder);color:#98a2b3}
/* A link button pressed with nothing selected: a nudge at the words
   rather than an error message for a mis-click. */
.dlg .rted.nosel{background:#fdf3f2}
.dlg .rturl{display:flex;gap:6px;padding:6px;background:#f7f8fa;
border-bottom:1px solid #e3e6ea}
.dlg .rturl[hidden]{display:none}
.dlg .rturl input{flex:1;margin:0;font-size:12px;padding:5px 9px}
.dlg .rturl button{padding:4px 10px;font-size:12px}
.dlg textarea.tmono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px}
.dlg .fld label.chk{display:flex;gap:8px;align-items:center;font-size:13px;color:#475467;
font-weight:400;margin:0}
.dlg .chk input{width:auto;margin:0}
/* tab bar */
.dlg .tabs{display:flex;gap:4px;margin:0 0 14px;border-bottom:1px solid #e3e6ea}
/* display:flex above outranks the [hidden] attribute, which would
   otherwise leave every tabless dialog with a stray rule under its
   heading. */
.dlg .tabs[hidden]{display:none}
.dlg .tabs button{border:none;background:none;border-radius:0;padding:8px 14px;font-size:13px;
color:#667085;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}
.dlg .tabs button:hover{background:none;color:#1c2128}
.dlg .tabs button.on{color:#2149b8;border-bottom-color:#2f5fe0;font-weight:600}
.dlg select{width:100%;padding:8px 10px;border:1px solid #d9dce1;border-radius:8px;
font:inherit;font-size:13px;background:#fff}
/* Pinned under the scrolling body rather than scrolling with it. */
.dlg .acts{display:flex;justify-content:flex-end;gap:8px;flex:none}
/* The settings panels get a hairline to sit against, since their
   controls can run under it. A plain confirm has nothing to divide. */
.dlg.wide .acts{padding-top:14px;border-top:1px solid #e3e6ea}
.dlg button{font:inherit;color:#1c2128;background:#fff;border:1px solid #d9dce1;
border-radius:8px;padding:7px 16px;cursor:pointer;font-size:13px}
.dlg button:hover{background:#f4f5f7}
.dlg button.ok{background:#2f5fe0;border-color:#2f5fe0;color:#fff}
.dlg button.ok:hover{background:#2149b8}
.dlg button.ok.danger{background:#c0392b;border-color:#c0392b}
.dlg button.ok.danger:hover{background:#a03024}
.post-pill{position:fixed;top:16px;right:16px;z-index:2147482999;display:flex;align-items:center;gap:7px;
background:var(--cms-chrome-bg);color:var(--cms-chrome-fg);border:none;border-radius:999px;
padding:9px 15px;font-size:13px;
line-height:1;cursor:pointer;
box-shadow:var(--cms-chrome-shadow-sm),inset 0 0 0 1px var(--cms-chrome-ring)}
.post-pill:hover{background:var(--cms-chrome-hi)}
.post-pill[hidden]{display:none}
.locs{display:flex;gap:2px;align-items:center}
.locs .loc{font-size:11px;letter-spacing:.04em;padding:4px 7px;border-radius:999px;
border:1px solid transparent;opacity:.6}
.locs .loc.on{border-color:var(--cms-chrome-line-2);opacity:1;cursor:default}
.locs .loc:hover{opacity:1}
`;

  // ../src/light.css
  var light_default = `/* Light-DOM styles for region outlines while editing. Imported as text
 * by shell.js and injected into <head> \u2014 these rules style the host
 * page's own content (regions, sections, snippets), which the shadow
 * root can't reach. */

/* ---- chrome palette ----
   The light-DOM half of the tokens styles.css defines for the shadow
   root: same names, same two schemes, declared again because a shadow
   root's custom properties do not reach out into the page. What lives
   out here is the chrome that has to sit in the host's own markup \u2014
   the section pills, the wrench menu beside the site nav \u2014 plus the
   strip TinyMCE renders its toolbar into.

   shell.js puts .cms-chrome-light on <body> for the light scheme. ---- */
:root{
--cms-chrome-bg:#1c2128;
--cms-chrome-hi:#2a3140;
--cms-chrome-menu:#242a33;
--cms-chrome-fg:#fff;
--cms-chrome-line:rgba(255,255,255,.28);
--cms-chrome-ring:transparent;
--cms-wash-1:rgba(255,255,255,.1);
--cms-wash-2:rgba(255,255,255,.14);
--cms-wash-3:rgba(255,255,255,.18);
--cms-chrome-dngr:#fca5a5;
--cms-chrome-dngr-wash:rgba(252,165,165,.2);
--cms-chrome-shadow:0 8px 24px rgba(0,0,0,.4);
--cms-chrome-shadow-sm:0 4px 12px rgba(0,0,0,.35);
}
body.cms-chrome-light{
--cms-chrome-bg:#fff;
--cms-chrome-hi:#f1f3f6;
--cms-chrome-menu:#fff;
--cms-chrome-fg:#1c2128;
--cms-chrome-line:#d9dce1;
--cms-chrome-ring:#dfe3e8;
--cms-wash-1:rgba(28,33,40,.06);
--cms-wash-2:rgba(28,33,40,.08);
--cms-wash-3:rgba(28,33,40,.1);
--cms-chrome-dngr:#c0392b;
--cms-chrome-dngr-wash:rgba(192,57,43,.1);
--cms-chrome-shadow:0 8px 24px rgba(15,18,25,.22);
--cms-chrome-shadow-sm:0 4px 12px rgba(15,18,25,.2);
}

/* The tool rail is fixed to the left edge; push the page content
   right so the rail sits beside it instead of covering it. The
   transition matches the rail's appearance. */
body{transition:margin-left .25s ease}
body.cms-editing{margin-left:56px}
/* The shared TinyMCE toolbar is pinned to the top of the viewport
   (#cms-mce-toolbar), which works for the page's own content: a region
   under it can be scrolled out from beneath it. The notice bar cannot \u2014
   it is the first thing in the document, so at scroll 0 it sits under
   the toolbar and there is nowhere to scroll to. Editing it was
   therefore very nearly impossible.

   So edit mode reserves the toolbar's lane above the bar, exactly as it
   reserves the left edge for the rail. The space is claimed on entering
   edit mode rather than on focusing the bar, so the thing being clicked
   never moves out from under the pointer \u2014 and the toolbar then opens
   in the gap directly above the region it belongs to. Only a bar at the
   top of the page needs this; one a template placed somewhere else is
   the host's own layout and is left alone. */
body.cms-editing > [data-cms-notice]:first-child{margin-top:76px;transition:margin-top .25s ease}
.cms-editing [data-cms-region]{outline:1.5px dashed rgba(47,95,224,.6);outline-offset:3px;min-height:1em}
.cms-editing [data-cms-region]:hover,.cms-editing [data-cms-region]:focus{outline-style:solid}
.cms-editing [data-cms-region]:empty::before{content:'Click to edit\u2026';opacity:.4}
/* The page title reads as editable the same way a text region does. It
   is inline inside the host's heading, so the outline hugs the words. */
.cms-editing [data-cms-title]{outline:1.5px dashed rgba(47,95,224,.6);outline-offset:3px;min-height:1em}
.cms-editing [data-cms-title]:hover,.cms-editing [data-cms-title]:focus{outline-style:solid}
.cms-editing [data-cms-image]{outline:1.5px dashed rgba(224,122,47,.75);outline-offset:3px;cursor:pointer}
.cms-editing [data-cms-image]:hover{outline-style:solid}
/* TinyMCE inline adds its own focus outline; ours is enough. */
.cms-editing [data-cms-region].mce-edit-focus{outline:1.5px solid rgba(47,95,224,.6)}
#cms-mce-toolbar > *{pointer-events:auto;box-shadow:0 4px 16px rgba(0,0,0,.18);border-radius:8px}

/* Sections */
.cms-editing [data-cms-section]{position:relative;outline:1.5px dashed rgba(30,126,78,.55);outline-offset:-3px}
.cms-editing [data-cms-section]:hover{outline-style:solid}
.cms-editing [data-cms-section-content]{min-height:2em}
/* Straddles the section's top edge (half above, half below) so it reads
 * as a tab on the boundary instead of covering the first line of a
 * wide/full-width section's content. Dimmed until the section (or the
 * pill itself) is hovered \u2014 low idle opacity rather than hidden so it
 * stays discoverable, and still works on touch where hover needs a tap. */
.cms-sec-ui{position:absolute;top:0;right:12px;transform:translateY(-50%);
z-index:2147482996;display:flex;gap:2px;
background:var(--cms-chrome-bg);border:1px solid var(--cms-chrome-line);border-radius:999px;
padding:4px 6px;box-shadow:var(--cms-chrome-shadow-sm);
opacity:.25;transition:opacity .15s ease}
.cms-editing [data-cms-section]:hover .cms-sec-ui,.cms-sec-ui:hover{opacity:1}
.cms-sec-ui button{font:15px/1 system-ui,sans-serif;color:var(--cms-chrome-fg);background:transparent;
border:none;border-radius:999px;padding:6px 9px;cursor:pointer}
.cms-sec-ui button svg{display:block;width:15px;height:15px;fill:currentColor}
.cms-sec-ui button:hover{background:var(--cms-wash-3)}
.cms-sec-ui button[data-secact='del']{color:var(--cms-chrome-dngr)}
.cms-sec-ui button[data-secact='del']:hover{background:var(--cms-chrome-dngr-wash)}
/* Hidden when the area it adds to is full; the host page's own reset
   must not be able to bring it back. */
.cms-add-section[hidden],.cms-sec-ui button[hidden]{display:none!important}
.cms-add-section{padding:14px;text-align:center}
.cms-add-section button{font:13px system-ui,sans-serif;color:#2149b8;background:#e8edfb;
border:1.5px dashed #2f5fe0;border-radius:10px;padding:10px 18px;cursor:pointer}
.cms-add-section button:hover{background:#dbe4fa}
/* Names the area a button adds to, on pages with more than one. */
.cms-add-region{margin-left:7px;padding:2px 7px;border-radius:999px;
background:rgba(33,73,184,.14);font-size:11px;letter-spacing:.02em}

/* Buttons (a.cms-btn): click while editing for gear/trash chrome. */
.cms-editing a.cms-btn{cursor:pointer}
.cms-editing a.cms-btn:hover{outline:1.5px dashed rgba(224,122,47,.75);outline-offset:2px}

/* Snippet blocks (.cms-snippet): dotted outline while editing;
 * click for drag-handle/trash chrome. !important beats host CSS
 * (e.g. Tailwind preflight/utilities) that also sets outlines. */
.cms-editing .cms-snippet{outline:1.5px dotted rgba(139,92,246,.6)!important;outline-offset:4px}
.cms-editing .cms-snippet:hover{outline-style:solid!important}

/* The column the column tool is acting on. Every button on that toolbar
 * changes one column and leaves the rest alone, so which one it has hold
 * of has to be visible \u2014 a row of identical cells is exactly where a
 * guess goes wrong. Inset offset so the tint hugs the cell instead of
 * bleeding into its neighbour's gutter. */
.cms-editing .cms-col-active{outline:1.5px solid rgba(47,95,224,.55)!important;
outline-offset:-1px;background-color:rgba(47,95,224,.05)}

/* Admin tools (admintools.js): a wrench button appended to the site
 * nav's item list, so it spaces like one more menu item (pinned
 * top-left on pages without a nav) with the everyday admin actions.
 * Light DOM, so every rule is explicit \u2014 host CSS (Tailwind preflight
 * etc.) must not restyle it. */
.cms-admin-li{list-style:none;display:flex;align-items:center;margin:0;padding:0}
#cms-admin-tools{position:relative;display:inline-flex;line-height:0}
#cms-admin-tools.cms-fixed{position:fixed;top:12px;left:12px;z-index:2147482996}
#cms-admin-tools-btn{display:flex;align-items:center;justify-content:center;width:30px;height:30px;
padding:0;border:none;border-radius:50%;background:var(--cms-chrome-bg);color:var(--cms-chrome-fg);
cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.25),inset 0 0 0 1px var(--cms-chrome-ring)}
#cms-admin-tools-btn:hover{background:var(--cms-chrome-hi)}
#cms-admin-tools-btn svg{width:14px;height:14px;fill:currentColor}
#cms-admin-tools .cms-admin-menu{position:absolute;top:calc(100% + 8px);left:0;z-index:2147482997;
display:none;flex-direction:column;background:var(--cms-chrome-menu);border-radius:12px;padding:6px;
min-width:170px;box-shadow:var(--cms-chrome-shadow),inset 0 0 0 1px var(--cms-chrome-ring);
text-align:left}
#cms-admin-tools.cms-open .cms-admin-menu{display:flex}
#cms-admin-tools.cms-align-right .cms-admin-menu{left:auto;right:0}
#cms-admin-tools .cms-admin-menu button,#cms-admin-tools .cms-admin-menu a{
font:13px/1.4 system-ui,sans-serif;color:var(--cms-chrome-fg);background:none;border:none;border-radius:8px;
padding:8px 12px;margin:0;text-align:left;cursor:pointer;white-space:nowrap;text-decoration:none;display:block}
#cms-admin-tools .cms-admin-menu button:hover,#cms-admin-tools .cms-admin-menu a:hover{
background:var(--cms-wash-1);color:var(--cms-chrome-fg)}
#cms-admin-tools .cms-admin-menu hr{border:none;border-top:1px solid var(--cms-wash-2);margin:4px 6px}

/* Site menus ({{cmsNav}}): while editing, clicking an item (long-press
 * on touch) opens its settings and drag rearranges; "\uFF0B" chips add
 * items. A mouse click on a dropdown toggle edits the dropdown itself,
 * so hovering opens its panel to keep the items inside reachable. */
.cms-editing nav[data-cms-menu]{outline:1.5px dashed rgba(47,95,224,.45);outline-offset:6px;
border-radius:2px;position:relative}
/* Hovering the nav explains the interaction; the delay keeps it from
 * flashing on every pass-over, and it gets out of the way mid-drag. */
.cms-editing nav[data-cms-menu]::after{content:'Click a menu item to edit it \u2014 drag to rearrange';
position:absolute;top:calc(100% + 10px);left:0;z-index:2147482995;
font:11px/1.4 system-ui,sans-serif;color:var(--cms-chrome-fg);background:var(--cms-chrome-bg);
padding:5px 10px;
border-radius:6px;box-shadow:var(--cms-chrome-shadow-sm),inset 0 0 0 1px var(--cms-chrome-ring);
white-space:nowrap;
pointer-events:none;opacity:0;transition:opacity .15s ease .4s}
.cms-editing nav[data-cms-menu]:hover::after{opacity:1}
body.cms-nav-dragging nav[data-cms-menu]::after{display:none}
/* An open (or hover-opened) dropdown panel occupies the same spot as
 * the hint \u2014 the panel wins. */
.cms-editing nav[data-cms-menu]:has(.cms-nav-drop.cms-open)::after,
.cms-editing nav[data-cms-menu]:has(.cms-nav-drop:hover)::after{display:none}
.cms-editing nav[data-cms-menu] .cms-nav-item{cursor:pointer}
.cms-editing nav[data-cms-menu] .cms-nav-drop:hover>.cms-nav-sub{display:block}
.cms-nav-addli button{font:13px/1 system-ui,sans-serif;color:#2149b8;background:#e8edfb;
border:1.5px dashed #2f5fe0;border-radius:8px;width:24px;height:24px;cursor:pointer;padding:0}
.cms-nav-addli button:hover{background:#dbe4fa}
.cms-nav-sub .cms-nav-addli{padding:.25em .9em}
/* The vacated slot reads as a placeholder while its item is airborne. */
.cms-nav-dragli{opacity:.3;outline:1.5px dashed rgba(47,95,224,.5);outline-offset:2px;border-radius:4px}
body.cms-nav-dragging{user-select:none;-webkit-user-select:none;cursor:grabbing}
body.cms-nav-dragging .cms-nav-addli{opacity:.25}
#cms-nav-ind{position:fixed;z-index:2147482996;background:#2f5fe0;border-radius:2px;
pointer-events:none;display:none;transition:left .07s ease,top .07s ease,width .07s ease,height .07s ease}
/* The drag ghost: a pill with the dragged item's label that follows the
 * pointer, dims when there's nowhere to drop, and settles into place on
 * release (transition set inline by settleGhost). */
#cms-nav-ghost{position:fixed;left:0;top:0;z-index:2147482997;pointer-events:none;
display:flex;align-items:center;gap:7px;white-space:nowrap;will-change:transform;opacity:.5;
font:13px/1.3 system-ui,sans-serif;color:#1c2128;background:#fff;padding:7px 13px;
border:1px solid rgba(0,0,0,.12);border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.28)}
#cms-nav-ghost .sub{color:#6b7280;font-size:11px}
#cms-nav-ghost.nodrop{opacity:.25}

/* Video slots: a click-to-fill placeholder from the video snippets.
 * While editing, players and embeds go click-through so a click reaches
 * the gear/trash chrome (buttons.js hit-tests their rectangles) instead
 * of playing the video or vanishing into a cross-origin iframe. */
.cms-editing [data-cms-video-slot],.cms-editing [data-cms-photo-slot],.cms-editing [data-cms-map-slot]{cursor:pointer}
.cms-editing [data-cms-video-slot]:hover,.cms-editing [data-cms-photo-slot]:hover,.cms-editing [data-cms-map-slot]:hover{outline:1.5px solid rgba(139,92,246,.6);outline-offset:2px}
.cms-editing [data-cms-region] iframe,.cms-editing [data-cms-sections] iframe,
.cms-editing [data-cms-region] video,.cms-editing [data-cms-sections] video{pointer-events:none}

/* Flexible-space snippet: invisible on the live site, visible and
 * click-to-adjust while editing. */
.cms-editing .cms-spacer{position:relative;cursor:pointer;min-height:14px;
outline:1.5px dashed rgba(217,119,6,.55);outline-offset:-2px;
background:repeating-linear-gradient(-45deg,rgba(217,119,6,.06),rgba(217,119,6,.06) 8px,transparent 8px,transparent 16px)}
.cms-editing .cms-spacer:hover{outline-style:solid}
.cms-editing .cms-spacer::after{content:'\u2195 Space \xB7 ' attr(data-height) ' \u2014 click to adjust';
position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
font:11px system-ui,sans-serif;color:#b45309;white-space:nowrap;pointer-events:none}

/* Custom-code blocks: entering edit mode empties the block back to the
   placeholder stored content holds, so while editing there is nothing to
   show but the name. Every other state \u2014 a visitor's page, and a
   logged-in editor's while merely viewing \u2014 has the entry's markup
   inside this same wrapper, which is why the card styling is scoped to
   edit mode. */
.cms-editing .cms-code{position:relative;min-height:52px;cursor:pointer;
outline:1.5px dashed rgba(37,99,235,.55);outline-offset:-2px;
background:repeating-linear-gradient(-45deg,rgba(37,99,235,.05),rgba(37,99,235,.05) 8px,transparent 8px,transparent 16px)}
.cms-editing .cms-code:hover{outline-style:solid}
.cms-editing .cms-code::after{content:'\u27E8/\u27E9 Custom code \xB7 ' attr(data-cms-code);
position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
font:11px system-ui,sans-serif;color:#1d4ed8;white-space:nowrap;pointer-events:none}

/* Untranslated regions in edit mode: content shown is default-language
   fallback until it is edited in this locale. */
body.cms-editing [data-cms-fallback] {
    outline: 2px dashed #f0b429 !important;
    outline-offset: 3px;
}
`;

